// hai pg.Client RIÊNG cho 2 phiên — KHÔNG dùng pool
const a = new pg.Client({ connectionString: CONN });
const b = new pg.Client({ connectionString: CONN });

async function round(no, a, b, beginSql, isoLabel) {
  await a.query(beginSql);           // A mở transaction
  const { rows: iso } =
    await a.query('SHOW transaction_isolation');
  const first = await readTotal(a);  // A đọc lần 1

  await b.query(SQL_BUMP, [ORDER_ID, BUMP]);
  await b.query('COMMIT');           // B ghi + COMMIT

  const second = await readTotal(a); // A đọc lần 2
  await a.query('COMMIT');
  return { first, second, changed: first !== second };
}

// giữa 2 vòng CHỈ đổi đúng câu BEGIN của phiên A:
r1 = await round(1, a, b, 'BEGIN', 'READ COMMITTED');
r2 = await round(2, a, b,
  'BEGIN ISOLATION LEVEL REPEATABLE READ', 'REPEATABLE READ');
